-- Bloco 9/10: 10 perguntas de O Que é o Espiritismo.
-- Seguro para executar individualmente; não altera perguntas existentes.
INSERT INTO public.questions
  (book, statement, option_a, option_b, option_c, option_d, option_e,
   correct_option, explanation, reference, difficulty, active)
VALUES
  ('o_que_e_espiritismo', 'No Capítulo III (''Suicídio'', itens 155 a 157), qual é o ensinamento constante de todos os Espíritos sobre o suicídio?', 'O homem nunca tem o direito de dispor da própria vida; o suicídio é sempre uma transgressão da lei de Deus que agrava os sofrimentos do Espírito.', 'O suicídio é permitido quando a pessoa sofre de doença física incurável.', 'O suicida alcança imediatamente o repouso e o esquecimento de suas dores.', 'O suicídio apressa a evolução espiritual quando motivado por desgosto amoroso.', 'A alma do suicida desintegra-se no instante em que o coração para de bater.', 'A', 'Nos itens 155 a 157, Kardec registra que o suicida procura fugir de um sofrimento passageiro e cai em torturas morais e perispirituais muito mais longas e terríveis.', 'O Que é o Espiritismo - Cap. III, itens 155 a 157', 'facil', true),
  ('o_que_e_espiritismo', 'Segundo o Capítulo III (item 156), por que o suicida sente por longo tempo após a morte todas as angústias e impressões da agonia física?', 'Porque o corpo material continua respirando dentro do túmulo.', 'Porque na morte violenta provocada antes do termo natural os laços entre o perispírito e o corpo estavam cheios de vitalidade e só se rompem lentamente.', 'Porque os bons Espíritos recusam-se a ouvir qualquer prece em favor dele.', 'Porque ele perde para sempre a capacidade de arrepender-se.', 'Porque o fluido cósmico congela-se ao redor do local do sepultamento.', 'B', 'Na morte natural a vida orgânica extingue-se pouco a pouco e o desprendimento é suave; no suicídio os laços vitais são quebrados à força em plena vitalidade, repercutindo dolorosamente no perispírito.', 'O Que é o Espiritismo - Cap. III, item 156', 'expert', true),
  ('o_que_e_espiritismo', 'De acordo com o Capítulo III (''Loucura, idiotia'', itens 158 a 162), o Espírito do louco ou do idiota de nascença é uma alma inferior ou privada de inteligência?', 'Sim, é uma alma criada sem o princípio da razão humana.', 'Sim, trata-se do espírito de um animal encarnado por engano em corpo humano.', 'Não; o Espírito em si pode ser inteligente, mas acha-se impedido de manifestar seu pensamento pela imperfeição ou lesão dos órgãos cerebrais que lhe servem de instrumento.', 'Não possui alma própria, vivendo apenas pela vida vegetativa do corpo.', 'Perdeu definitivamente a memória e a consciência por toda a eternidade.', 'C', 'O cérebro é o instrumento de manifestação do pensamento na vida corpórea: assim como o mais hábil músico não pode tirar sons harmoniosos de um instrumento quebrado, o Espírito fica tolhido por órgãos imperfeitos.', 'O Que é o Espiritismo - Cap. III, itens 158 a 162', 'dificil', true),
  ('o_que_e_espiritismo', 'Segundo o Capítulo III (itens 160 a 162), com que finalidade moral e educativa um Espírito inteligente pode ser submetido à dura prova da idiotia ou da loucura?', 'Por mero acidente biológico sem qualquer relação com a justiça de Deus.', 'Para premiar os Espíritos que já atingiram a santidade suprema.', 'Para demonstrar que a matéria governa soberanamente o destino da alma.', 'Como expiação do abuso que fez de sua inteligência, de seu orgulho ou de suas paixões em existência anterior, sofrendo o constrangimento de não poder exprimir-se.', 'Para isentar a família de qualquer dever de caridade e assistência.', 'D', 'No corpo do idiota o Espírito tem consciência interior de sua situação e sofre o constrangimento de não poder comunicar-se, expiando assim o abuso anterior de suas faculdades intelectuais.', 'O Que é o Espiritismo - Cap. III, itens 160 a 162', 'dificil', true),
  ('o_que_e_espiritismo', 'Na Biografia de Allan Kardec por Henri Sausse, qual memória premiada em 1831 pela Academia Real de Ciências de Arras o jovem professor Rivail escreveu?', 'Um tratado sobre a aplicação da eletricidade aos telégrafos marítimos.', 'Um estudo astronômico sobre as órbitas dos cometas periódicos.', 'Uma tese médica sobre o tratamento da febre amarela nas colônias.', 'Um romance histórico sobre os druidas da antiga Gália.', '''Qual o sistema de estudos mais em harmonia com as necessidades da época?''.', 'E', 'Henri Sausse destaca que em 1831 a Academia Real de Ciências de Arras premiou a notável memória pedagógica de Rivail sobre a reforma do ensino público na França.', 'O Que é o Espiritismo - Biografia de Allan Kardec (Henri Sausse)', 'medio', true),
  ('o_que_e_espiritismo', 'Segundo Henri Sausse, que resposta memorável deu o professor Rivail em 1854 quando o Sr. Fortier lhe disse que as mesas falavam ao serem interrogadas?', '''Só acreditarei quando o vir e quando me provarem que uma mesa tem cérebro para pensar, nervos para sentir e que possa tornar-se sonâmbula; até lá, permita que eu não veja nisso mais que um conto para fazer dormir em pé.''', '''Aceito imediatamente o prodígio, pois tudo no universo é sobrenatural e miraculoso.''', '''Jamais assistirei a uma sessão, porque a ciência oficial já proibiu tais estudos.''', '''As mesas falam porque são habitadas pelos gênios elementais da floresta.''', '''Publicarei amanhã mesmo um livro confirmando essas revelações sem precisar verificá-las.''', 'A', 'Essa resposta célebre mostra a prudência e o rigor científico de Rivail: ele não negou a possibilidade de uma força desconhecida, mas exigiu observação direta e explicação racional antes de admitir uma causa inteligente.', 'O Que é o Espiritismo - Biografia de Allan Kardec (Henri Sausse)', 'dificil', true),
  ('o_que_e_espiritismo', 'Conforme relata Henri Sausse na Biografia, qual era o nome do Espírito protetor de Allan Kardec, que se comunicou com ele pela médium Srta. Aline C. em 1856 confirmando sua missão?', 'O Espírito de São Luís.', 'O Espírito da Verdade (e também o seu Espírito familiar Zéfiro nas reuniões da família Baudin).', 'O Espírito de Emanuel Swedenborg.', 'O Espírito de Galileu Galilei.', 'O Espírito de Joana d''Arc.', 'B', 'Nas sessões da família Baudin manifestava-se o Espírito protetor Zéfiro (que lhe revelou o nome Allan Kardec), e em 1856 o Espírito da Verdade confirmou-lhe a árdua missão de codificar a Doutrina.', 'O Que é o Espiritismo - Biografia de Allan Kardec (Henri Sausse)', 'medio', true),
  ('o_que_e_espiritismo', 'Segundo a Biografia escrita por Henri Sausse, em que cidade espanhola ocorreu em 9 de outubro de 1861 o célebre auto de fé em que foram queimados trezentos volumes espíritas?', 'Em Madri.', 'Em Sevilha.', 'Em Barcelona.', 'Em Valência.', 'Em Salamanca.', 'C', 'Em 9 de outubro de 1861, por ordem do bispo de Barcelona, foram queimados em praça pública trezentos volumes e brochuras espíritas, fato que repercutiu imensamente a favor da divulgação do Espiritismo.', 'O Que é o Espiritismo - Biografia de Allan Kardec (Henri Sausse)', 'dificil', true),
  ('o_que_e_espiritismo', 'No Segundo Diálogo (''O Cético''), como o espírita explica por que a Ciência oficial não é competente para julgar a priori a questão dos Espíritos?', 'Porque todos os cientistas são inimigos declarados do progresso humano.', 'Porque a matemática e a física são ciências falsas e ilusórias.', 'Porque o Espiritismo proíbe que médicos e físicos estudem suas obras.', 'Porque as ciências exatas tratam apenas das leis da matéria bruta, enquanto o Espiritismo estuda o elemento espiritual e suas relações com a matéria, o que escapa aos instrumentos de laboratório.', 'Porque os Espíritos apagam a memória dos cientistas que entram nas reuniões.', 'D', 'Cada ciência tem a sua especialidade: a química e a física estudam a matéria inerte; querer submeter o Espírito livre ao cadinho ou ao bisturi é sair do objeto próprio das ciências materiais.', 'O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético', 'expert', true),
  ('o_que_e_espiritismo', 'No Segundo Diálogo, quando o Cético pergunta se o médium sente o pensamento do Espírito antes de escrever, o que Kardec esclarece?', 'Nunca; o médium fica sempre inconsciente como uma estátua de pedra.', 'Sempre; não existe nenhum médium que escreva sem saber antes toda a frase.', 'Apenas quando o Espírito comunicante é um parente próximo desencarnado.', 'Somente nas noites de tempestade elétrica.', 'Isso depende do tipo de mediunidade: no médium mecânico a mão escreve sem que ele tenha consciência; no médium intuitivo ou semimecânico o pensamento atravessa o seu cérebro no ato da escrita.', 'E', 'Kardec explica ao Cético a distinção entre o médium puramente passivo ou mecânico e o médium intuitivo ou semimecânico, mostrando como em ambos os casos se comprova a independência da ideia comunicada.', 'O Que é o Espiritismo - Cap. I, Segundo Diálogo: O Cético', 'medio', true);
ON CONFLICT (statement) DO NOTHING;

SELECT COUNT(*) AS perguntas_do_livro
FROM public.questions
WHERE book = 'o_que_e_espiritismo';